@media (hover: hover) {
  .btn:hover { background-size: 100% 100%; }
}
.btn:active {
  background-size: 100% 100%;
  transform: translateY(1px);
  transition-duration: 0ms;
}

/* ---------- Glazed header band ---------- */

.glaze {
  --ring: var(--on-glaze);
  position: relative;
  background: var(--glaze);
  color: var(--on-glaze);
}

/* The drip lives on its own decorative layer, so it never clips content or focus */
.glaze::after,
.foot::before,
.tile::after,
.ph::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  background: inherit;
  -webkit-mask: var(--drip) repeat-x top left / 15rem 100%;
  mask: var(--drip) repeat-x top left / 15rem 100%;
  pointer-events: none;
}

.glaze::after {
  top: calc(100% - 1px);
  height: 2.75rem;
  transform-origin: top;
}
@media (prefers-reduced-motion: no-preference) {
  .glaze::after { animation: drip 750ms var(--ease-out) 150ms both; }
}
@keyframes drip {
  from { transform: scaleY(0.3); }
  to { transform: scaleY(1); }
}

.nav {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.5rem 1.5rem;
  padding-block: 1rem;
}

.wordmark {
  font-family: var(--display);
  font-size: 1.5rem;
  line-height: 1.2;
  text-decoration: none;
  margin-right: auto;
}

.nav__links {
  display: flex;
  flex-wrap: wrap;
  gap: 0 0.25rem;
  margin: 0;
  padding: 0;
  list-style: none;
}
.nav__links a {
  display: inline-flex;
  align-items: center;
  min-height: 2.75rem;
  padding-inline: 0.6rem;
  text-decoration: none;
  font-weight: 500;
}
@media (hover: hover) {
  .nav__links a:hover { text-decoration: underline; }
}

.hero {
  display: grid;
  grid-template-columns: 1.3fr 1fr;
  align-items: end;
  gap: 3rem;
  padding-block: 4rem 0;
}

.hero__copy { padding-bottom: 4rem; }

h1 {
  font-size: clamp(2.4rem, 1.4rem + 4.6vw, 5rem);
  line-height: 1.05;
  letter-spacing: -0.02em;
  max-width: 14ch;
}

.hero__lede {
  margin-top: 1.5rem;
  max-width: 34rem;
  font-size: 1.1875rem;
  line-height: 1.6;
  color: var(--on-glaze-muted);
}

.hero__actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 1rem 1.75rem;
  margin-top: 2.25rem;
}

.link-light {
  display: inline-flex;
  align-items: center;
  min-height: 2.75rem;
  font-weight: 500;
  text-decoration: underline;
  text-decoration-thickness: 1px;
}

.hero__photo {
  position: relative;
  z-index: 2;
  margin-bottom: calc(var(--overhang) * -1);
  justify-self: end;
  width: 100%;
  max-width: 26rem;
}
.hero__photo .ph { aspect-ratio: 4 / 5; }

/* ---------- Photo placeholders: raw clay with a glazed lip ---------- */

.photo {
  position: relative;
  margin: 0;
}

.ph {
  position: relative;
  height: 100%;
  min-height: 10rem;
  border-radius: 0.4rem;
  overflow: hidden;
  background:
    repeating-radial-gradient(circle at 50% 120%, transparent 0 0.9rem, oklch(0.82 0.012 240 / 0.6) 0.9rem 1rem),
    var(--raw);
  box-shadow: 0 1.25rem 2.5rem -1.5rem oklch(0.24 0.02 255 / 0.45);
}
/* the glazed lip */
.ph::before {
  content: "";
  position: absolute;
  inset: 0 0 auto 0;
  height: 16%;
  background: var(--lip, var(--tenmoku));
}
.ph::after {
  top: calc(16% - 1px);
  height: 1.75rem;
  background: var(--lip, var(--tenmoku));
  -webkit-mask-size: 9rem 100%;
  mask-size: 9rem 100%;
}

.photo figcaption {
  position: absolute;
  left: 0.75rem;
  right: 0.75rem;
  bottom: 0.75rem;
  color: var(--ink);
  font-size: 0.9375rem;
  line-height: 1.4;
}

/* ---------- Workshops ---------- */

.workshops {
  padding-top: calc(var(--overhang) + 3.5rem);
  padding-bottom: 5rem;
}

.section-head { max-width: 38rem; }
.section-head h2 {
  font-size: clamp(2rem, 1.5rem + 2.2vw, 3rem);
  line-height: 1.1;
  letter-spacing: -0.015em;
}
.section-head p {
  margin-top: 1rem;
  color: var(--muted);
}

.ws-list {
  margin: 3rem 0 0;
  padding: 0;
  list-style: none;
  border-bottom: 1px solid var(--rule);
}

.ws {
  display: grid;
  grid-template-columns: 3.5rem minmax(0, 1fr) auto;
  gap: 1.25rem 2.5rem;
  align-items: start;
  padding-block: 2.25rem;
  border-top: 1px solid var(--rule);
}

.ws h3 {
  font-size: 1.75rem;
  line-height: 1.2;
}
.ws__body > p {
  margin-top: 0.5rem;
  max-width: 34rem;
}

.ws__facts {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem 2rem;
  margin: 1.25rem 0 0;
}
.ws__facts dt {
  font-size: 0.875rem;
  color: var(--muted);
}
.ws__facts dd {
  margin: 0;
  font-weight: 500;
}

.ws__buy {
  display: grid;
  justify-items: end;
  gap: 1rem;
  text-align: right;
}

.price {
  font-family: var(--display);
  font-size: 2.25rem;
  line-height: 1;
  font-variant-numeric: tabular-nums lining-nums;
}
.price span {
  display: block;
  margin-top: 0.4rem;
  font-family: var(--body);
  font-size: 0.9375rem;
  color: var(--muted);
}

/* Glaze test tile: raw clay, dipped two thirds of the way */
.tile {
  position: relative;
  display: block;
  width: 3.5rem;
  height: 4.5rem;
  margin-top: 0.3rem;
  border-radius: 0.3rem;
  overflow: hidden;
  background: var(--raw);
  box-shadow: 0 0.5rem 1rem -0.6rem oklch(0.24 0.02 255 / 0.5);
}
.tile::before {
  content: "";
  position: absolute;
  inset: 0 0 auto 0;
  height: 45%;
  background: var(--tile);
}
.tile::after {
  top: calc(45% - 1px);
  height: 1rem;
  background: var(--tile);
  -webkit-mask-size: 4rem 100%;
  mask-size: 4rem 100%;
}
.tile--cobalt { --tile: var(--glaze); }
.tile--celadon { --tile: var(--celadon); }
.tile--tenmoku { --tile: var(--tenmoku); }
.tile--tenmoku::before { background: linear-gradient(to bottom, var(--iron), var(--tenmoku) 55%); }

.ws-note {
  margin-top: 2rem;
  max-width: 44rem;
  color: var(--muted);
}
.ws-note a {
  color: var(--glaze);
  font-weight: 700;
  overflow-wrap: anywhere;
}

/* ---------- Studio gallery ---------- */

.studio { padding-bottom: 8rem; }

.gallery {
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  gap: 1.25rem;
  margin-top: 3rem;
}
.gallery__a { grid-column: 1 / 5; grid-row: 1 / 3; }
.gallery__b { grid-column: 5 / 7; --lip: var(--celadon); }
.gallery__c { grid-column: 5 / 7; --lip: var(--glaze); }
.gallery__d { grid-column: 2 / 7; }
.gallery__b .ph,
.gallery__c .ph { aspect-ratio: 4 / 3; }
.gallery__d .ph { aspect-ratio: 21 / 8; }

/* ---------- Footer: tenmoku, the glaze pools upward ---------- */

.foot {
  --ring: var(--on-glaze);
  position: relative;
  background: var(--tenmoku);
  color: var(--on-tenmoku);
  padding-block: 3.5rem 2rem;
}
.foot::before {
  bottom: calc(100% - 1px);
  height: 2.75rem;
  transform: scaleY(-1);
}

.foot__inner {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(14rem, 1fr));
  gap: 2rem 3rem;
}
.foot h2 {
  font-size: 1.25rem;
  margin-bottom: 0.5rem;
}
.foot .wordmark { font-size: 1.75rem; display: block; margin-bottom: 0.25rem; }
.foot p,
.foot address {
  font-style: normal;
  color: var(--on-tenmoku-muted);
}
.foot a {
  color: var(--on-tenmoku);
  font-weight: 500;
  overflow-wrap: anywhere;
}
.foot__small {
  margin-top: 3rem;
  font-size: 0.875rem;
  color: var(--on-tenmoku-muted);
}

/* ---------- Narrow screens ---------- */

@media (max-width: 52rem) {
  :root { --overhang: 4rem; }
  .hero {
    grid-template-columns: 1fr;
    gap: 0;
    padding-top: 2.5rem;
  }
  .hero__copy { padding-bottom: 2.5rem; }
  .hero__photo { max-width: 22rem; }

  .ws { grid-template-columns: 2.75rem minmax(0, 1fr); column-gap: 1.25rem; }
  .tile { width: 2.75rem; height: 3.5rem; }
  .ws__buy {
    grid-column: 2;
    justify-items: start;
    text-align: left;
  }

  .gallery { grid-template-columns: 1fr 1fr; }
  .gallery__a { grid-column: 1 / 3; grid-row: auto; }
  .gallery__a .ph { aspect-ratio: 4 / 3; }
  .gallery__b,
  .gallery__c { grid-column: auto; }
  .gallery__d { grid-column: 1 / 3; }
  .gallery__d .ph { aspect-ratio: 16 / 9; }
}

@media (max-width: 34rem) {
  .nav__links { order: 3; width: 100%; margin-left: -0.6rem; }
  .gallery { grid-template-columns: 1fr; }
  .gallery__a,
  .gallery__b,
  .gallery__c,
  .gallery__d { grid-column: auto; }
  .gallery .ph { aspect-ratio: 4 / 3; }
  .price span { display: inline; margin-left: 0.25rem; }
}

/* Reduced motion: no drip, no rise. Colour still changes on hover and press. */
@media (prefers-reduced-motion: reduce) {
  .btn { transition: none; }
  .btn:active { transform: none; }
}

@media (forced-colors: active) {
  .btn { border: 2px solid ButtonText; }
}

