/* Kiln & Co. Tokens and decisions are recorded in DESIGN.md. */

:root {
  /* Clay: unfired stoneware, cool grey */
  --clay: oklch(0.93 0.007 240);
  --slip: oklch(0.965 0.005 240);
  --raw: oklch(0.86 0.012 240);
  --ink: oklch(0.24 0.02 255);
  --muted: oklch(0.44 0.02 250);
  --rule: oklch(0.60 0.02 245);

  /* Glazes */
  --glaze: oklch(0.40 0.15 263);        /* cobalt */
  --glaze-deep: oklch(0.32 0.13 263);
  --on-glaze: oklch(0.97 0.01 250);
  --on-glaze-muted: oklch(0.86 0.04 255);
  --celadon: oklch(0.72 0.07 170);
  --tenmoku: oklch(0.22 0.025 45);
  --iron: oklch(0.50 0.11 45);
  --on-tenmoku: oklch(0.93 0.01 60);
  --on-tenmoku-muted: oklch(0.78 0.02 60);

  --ring: var(--glaze);

  /* The glaze-dip edge: the one signature shape */
